import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"What Is xShop?","description":"","frontmatter":{},"headers":[],"relativePath":"01-getting-started/01-what-is-xshop.md","filePath":"01-getting-started/01-what-is-xshop.md"}`),a={name:`01-getting-started/01-what-is-xshop.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="what-is-xshop" tabindex="-1">What Is xShop? <a class="header-anchor" href="#what-is-xshop" aria-label="Permalink to “What Is xShop?”">​</a></h1><p>An open-source Laravel-based system that lets you quickly set up a shop, a blog, or a client&#39;s website with minimal configuration and enjoy its benefits.</p><h2 id="core-features-and-differentiators" tabindex="-1">Core Features and Differentiators <a class="header-anchor" href="#core-features-and-differentiators" aria-label="Permalink to “Core Features and Differentiators”">​</a></h2><ul><li><strong>Exceptional flexibility</strong> across almost every dimension, dramatically reducing the need to modify code.</li><li><strong>Developer-friendly</strong>: built-in tools in the core allow you to add custom code to the system as quickly as possible.</li><li><strong>Native multilingual support</strong>: choose a language and run a multilingual site with confidence.</li><li><strong>SEO focus</strong>: the search-engine-friendly architecture resolves most technical SEO issues out of the box.</li><li><strong>WordPress/WooCommerce migration</strong> capability.</li><li><strong>Highly customizable theme system</strong>: you can change the site&#39;s appearance in any language at any time without hassle.</li></ul><h2 id="why-did-we-create-xshop" tabindex="-1">Why Did We Create xShop? <a class="header-anchor" href="#why-did-we-create-xshop" aria-label="Permalink to “Why Did We Create xShop?”">​</a></h2><p>After years of coding and building various websites, I discovered many painful boilerplate issues. Leveraging that experience, we built a maximally flexible, boilerplate-reduced system and released it to the open-source community under the GPL license.</p><h3 id="does-xshop-claim-to-be-perfect" tabindex="-1">Does xShop Claim to Be Perfect? <a class="header-anchor" href="#does-xshop-claim-to-be-perfect" aria-label="Permalink to “Does xShop Claim to Be Perfect?”">​</a></h3><p>No. Such a claim would be wildly exaggerated and unrealistic. However, we strive to identify and fix bugs quickly. Feel free to test us by opening an Issue.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};